CREATE TABLE schema_version(id INTEGER PRIMARY KEY CHECK(id=1),version INTEGER NOT NULL);
INSERT INTO schema_version VALUES(1,1);
CREATE TABLE users(id TEXT PRIMARY KEY,username TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1);
CREATE TABLE sessions(hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,csrf TEXT NOT NULL,expires INTEGER NOT NULL,age_until INTEGER NOT NULL DEFAULT 0,age_id TEXT,age_ref TEXT,age_deadline INTEGER,age_checked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE licenses(id TEXT PRIMARY KEY,provider_id TEXT NOT NULL UNIQUE,reference TEXT NOT NULL,category TEXT NOT NULL,starts INTEGER NOT NULL,ends INTEGER NOT NULL,countries TEXT NOT NULL,full_length INTEGER NOT NULL,native_hls INTEGER NOT NULL,drm_required INTEGER NOT NULL);
CREATE TABLE favorites(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,video_id TEXT NOT NULL REFERENCES licenses(id) ON DELETE CASCADE,added INTEGER NOT NULL,PRIMARY KEY(user_id,video_id));
CREATE TABLE history(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,video_id TEXT NOT NULL REFERENCES licenses(id) ON DELETE CASCADE,position REAL NOT NULL,watched INTEGER NOT NULL,PRIMARY KEY(user_id,video_id));
CREATE TABLE limits(key TEXT PRIMARY KEY,count INTEGER NOT NULL,reset INTEGER NOT NULL);
CREATE INDEX sessions_expiry ON sessions(expires);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE INDEX limits_expiry ON limits(reset);
CREATE TRIGGER password_reset AFTER UPDATE OF password_hash ON users WHEN NEW.password_hash<>OLD.password_hash BEGIN DELETE FROM sessions WHERE user_id=NEW.id; END;
CREATE TRIGGER account_disabled AFTER UPDATE OF enabled ON users WHEN NEW.enabled=0 BEGIN DELETE FROM sessions WHERE user_id=NEW.id; END;
